<?php declare(strict_types=1); namespace Annam; $title=$order['order_no'];$subtitle=BillingPortal::channelLabel($order['channel']).' · '.BillingPortal::paymentLabel($order['payment_status']); ?>
<?php if($intent): ?><section class="o-card"><h2>Online payment · Razorpay <?= e(strtoupper($intent['mode'])) ?></h2><p>Provider state: <?= e($intent['state']) ?> · <?= e(BillingPortal::paymentLabel($order['payment_status'])) ?></p><?php if($intent['mode']==='test'): ?><p>TEST PAYMENT — no real money is collected and no financial bill is issued.</p><?php endif; ?><?php if($intent['bill_error']): ?><p role="alert"><?= e($intent['bill_error']) ?></p><?php endif; ?><?php if(($user['is_superuser']??false)||($user['role']??'')==='owner'): ?><form method="post" action="reconcile/"><?= csrf() ?><button class="o-btn">Refresh provider status</button></form><?php if($intent['state']==='captured'): ?><form method="post" action="refund/"><?= csrf() ?><label class="o-field">Full refund reason<input class="o-input" name="reason" maxlength="200" required></label><label class="o-check"><input type="checkbox" name="confirmed_refund" value="yes" required><span class="o-switch-ui" aria-hidden="true"><i></i></span><b>Confirm full refund</b></label><button class="o-btn">Request full refund</button></form><?php endif; endif; ?></section><?php endif; ?>
<p><a href="/billing/<?= e($channel) ?>/">← Back to source orders</a></p><div class="b-order-grid"><section class="o-card"><h2>Booking details</h2><dl class="b-order-meta"><div><dt>Customer</dt><dd><?= e($order['address']['recipient_name']??'') ?></dd></div><div><dt>Mobile number</dt><dd><?= e($order['address']['phone']??'') ?></dd></div><div><dt>Delivery / collection</dt><dd><?= e(($order['address']['fulfilment']??'')==='Collection'?'Collection at kitchen':implode(', ',array_filter(array_intersect_key($order['address'],array_flip(['line1','line2','area','city','state','country','pincode']))))) ?></dd></div><div><dt>Order status</dt><dd><?= e(ucfirst(str_replace('_',' ',$order['status']))) ?><?php if($order['delivery_date']): ?><br><?= e(date('D, j M Y',strtotime($order['delivery_date']))) ?><?php endif; ?></dd></div></dl><ul class="o-rows o-rows-static"><?php foreach($order['items'] as $line): ?><li><span><b><?= e($line['name']) ?></b><small><?= e($line['quantity']) ?> × <?= money($line['unit_price']) ?></small></span><b><?= money($line['line_total']) ?></b></li><?php endforeach; ?></ul><dl class="b-totals"><div><dt>Subtotal</dt><dd><?= money($order['subtotal']) ?></dd></div><div><dt>Delivery</dt><dd><?= money($order['delivery_fee']) ?></dd></div><?php if(Money::parse($order['discount'])): ?><div><dt>Discount</dt><dd>−<?= money($order['discount']) ?></dd></div><?php endif; ?><div class="b-grand-total"><dt>Final total</dt><dd><?= money($order['total']) ?></dd></div></dl><p><a aria-label="Manage delivery" href="/manage/orders/<?= e($order['id']) ?>/">Manage delivery →</a></p></section>
<section class="o-card"><h2>Payment &amp; bill</h2><p class="b-step-note">Issue a bill, then record payment when it is actually received.</p><div class="b-payment-state <?= $order['payment_status']==='paid'?'is-paid':'' ?>"><strong><?= e(BillingPortal::paymentLabel($order['payment_status'])) ?></strong> · <?= money($order['total']) ?></div><div class="b-payment-actions"><?php if($invoice): ?><a class="o-btn o-btn-primary" href="/billing/bills/<?= e($invoice['id']) ?>/">View / print bill <?= e($invoice['number']) ?></a> <a class="o-btn" href="/billing/bills/<?= e($invoice['id']) ?>/download/">Download invoice PDF</a><?php endif; ?><?php if(($intent['mode']??'')==='test'): ?><p>Test payments do not generate real bills.</p><?php elseif($order['payment_status']==='paid'): ?><?php if(!$invoice): ?><form method="post" action="bill/"><?= csrf() ?><button class="o-btn o-btn-primary">Generate bill</button></form><?php endif; ?><?php elseif($intent||$order['payment_mode']==='online'): ?><?php if($order['payment_status']!=='refunded'&&$order['status']!=='cancelled'): ?><p><strong>Payment not received.</strong> Awaiting verified online payment.</p><?php endif; ?><p>Online payments are verified through Razorpay and cannot be marked paid manually.</p><a class="o-btn" href="/manage/orders/<?= e($order['id']) ?>/">Check provider payment status</a><?php elseif(!in_array($order['payment_status'],['paid','refunded'],true)&&$order['status']!=='cancelled'): ?>
<p><strong><?= $order['payment_mode']==='cod'?'Payment not received — collect on delivery.':'Payment is awaiting receipt.' ?></strong> Delivery status alone does not confirm payment.</p><?php if($order['payment_status']!=='cod_pending'): ?><form method="post" action="payment/"><?= csrf() ?><button class="o-btn" name="action" value="collect_on_delivery">Payment not received · collect on delivery</button></form><?php endif; ?>
<?php if(!$invoice): ?><form method="post" action="bill/"><?= csrf() ?><button class="o-btn o-btn-primary" name="issue_unpaid" value="yes">Issue bill — payment not received</button></form><?php endif; ?><p>Confirm only after receiving the full payment. For COD, confirm cash collection.</p><form method="post" action="payment/"><?= csrf() ?><label class="o-check"><input type="checkbox" name="confirmed" value="yes" required><span class="o-switch-ui" aria-hidden="true"><i></i></span><b>Full payment of <?= money($order['total']) ?> received</b><span class="o-toggle-state" aria-hidden="true"><span class="when-on">On</span><span class="when-off">Off</span></span></label><label class="b-payment-reference" for="collection-reference">Payment reference or collection note (optional)</label><input id="collection-reference" class="o-input" name="reference" maxlength="120" placeholder="UTR / payment reference / collection note"><button class="o-btn o-btn-primary"><?= $invoice?'Confirm payment received':'Confirm payment &amp; issue bill' ?></button></form><?php else: ?><p>This order cannot accept payment.</p><?php endif; ?></div><p><a href="/billing/settings/">Billing settings</a> — shared by manual, website and WhatsApp bills.</p></section></div>
